import { SensorCommit, IncidentReport, DriftDetection, Annotation } from '../types';
import { generateSensorSequence, getDefaultCalibration, getBadCalibration, generateScenarioPointCloud } from './sensorData';
import { createCommit } from '../algorithms/contentAddressable';
import { detectDrift } from '../algorithms/driftDetection';

/**
 * Pre-built incident scenarios for demo
 */

export function createIncidentScenario(): {
  commits: SensorCommit[];
  incident: IncidentReport;
} {
  const startTime = Date.now() - 86400000; // 24 hours ago

  // Commit 1: Initial good state
  const readings1 = generateSensorSequence(5000, false);
  const commit1 = createCommit(
    null,
    'alice@delby.ai',
    'Initial sensor calibration',
    getDefaultCalibration(),
    readings1
  );

  // Commit 2: Updated calibration (still good)
  const readings2 = generateSensorSequence(5000, false);
  const commit2 = createCommit(
    commit1,
    'bob@delby.ai',
    'Update LiDAR transform matrix',
    getDefaultCalibration(),
    readings2
  );

  // Commit 3: Bad calibration introduced (drift!)
  const readings3 = generateSensorSequence(5000, true, 47); // 47ms drift
  const commit3 = createCommit(
    commit2,
    'alice@delby.ai',
    'Test new camera settings',
    getBadCalibration(),
    readings3
  );

  // Detect drift in commit3
  const drifts = detectDrift(readings3, 20);

  // Create incident report
  const incident: IncidentReport = {
    id: 'incident-001',
    title: 'Perception Failure: LiDAR-Camera Desync',
    description: 'Vehicle detection failed due to 47ms timestamp drift between LiDAR and camera. The camera frame was delayed, causing the fusion algorithm to associate the wrong LiDAR points with the detected bounding box.',
    commitHash: commit3.hash,
    timestamp: new Date(startTime + 15000),
    drifts,
    annotations: [
      {
        id: 'ann-1',
        author: 'alice@delby.ai',
        timestamp: new Date(startTime + 16000),
        text: 'Reproduced locally - the camera driver update introduced a processing delay',
        sensorId: 'camera-0'
      },
      {
        id: 'ann-2',
        author: 'bob@delby.ai',
        timestamp: new Date(startTime + 17000),
        text: 'Rolling back to commit ' + commit2.hash.slice(0, 8) + ' fixes the issue',
        timeRange: [3000, 4000]
      }
    ]
  };

  return {
    commits: [commit1, commit2, commit3],
    incident
  };
}

/**
 * Create branch scenario (testing different calibration params)
 */
export function createBranchScenario(): {
  mainCommits: SensorCommit[];
  branchCommits: SensorCommit[];
} {
  const startTime = Date.now() - 3600000; // 1 hour ago

  // Main branch
  const readings1 = generateSensorSequence(3000, false);
  const mainCommit1 = createCommit(
    null,
    'alice@delby.ai',
    'Production calibration v1.0',
    getDefaultCalibration(),
    readings1
  );

  const readings2 = generateSensorSequence(3000, false);
  const mainCommit2 = createCommit(
    mainCommit1,
    'alice@delby.ai',
    'Update for hardware revision B',
    getDefaultCalibration(),
    readings2
  );

  // Experimental branch
  const branchReadings1 = generateSensorSequence(3000, false);
  const experimentalCal = {
    ...getDefaultCalibration(),
    timestampOffsets: {
      lidar: 5,
      camera: -3,
      imu: 2
    }
  };

  const branchCommit1 = createCommit(
    mainCommit1,
    'bob@delby.ai',
    'Experiment: optimize timestamp sync',
    experimentalCal,
    branchReadings1
  );
  branchCommit1.branches = ['experimental-sync'];

  const branchReadings2 = generateSensorSequence(3000, false);
  const branchCommit2 = createCommit(
    branchCommit1,
    'bob@delby.ai',
    'Fine-tune camera offset',
    {
      ...experimentalCal,
      timestampOffsets: {
        lidar: 5,
        camera: -5,
        imu: 2
      }
    },
    branchReadings2
  );
  branchCommit2.branches = ['experimental-sync'];

  return {
    mainCommits: [mainCommit1, mainCommit2],
    branchCommits: [branchCommit1, branchCommit2]
  };
}

/**
 * Create full commit history with multiple features
 */
export function createFullHistory(): SensorCommit[] {
  const commits: SensorCommit[] = [];
  const authors = ['alice@delby.ai', 'bob@delby.ai', 'carol@delby.ai'];
  const messages = [
    'Initial sensor setup',
    'Calibrate LiDAR extrinsics',
    'Update camera intrinsics',
    'Fix IMU orientation',
    'Optimize sync parameters',
    'Test under high-speed conditions',
    'Adjust for temperature drift',
    'Merge experimental changes',
    'Production release v1.1',
    'Hotfix: camera timestamp offset'
  ];

  let parent: SensorCommit | null = null;

  for (let i = 0; i < 10; i++) {
    const readings = generateSensorSequence(2000, i === 6, i === 6 ? 47 : 0);
    const cal = i === 6 ? getBadCalibration() : getDefaultCalibration();

    const commit = createCommit(
      parent,
      authors[i % authors.length],
      messages[i],
      cal,
      readings
    );

    if (i === 6) {
      commit.tags = ['v1.0-broken'];
    } else if (i === 8) {
      commit.tags = ['v1.1'];
    }

    commits.push(commit);
    parent = commit;
  }

  return commits;
}

/**
 * Generate synthetic drift over time for visualization
 */
export function generateDriftTimeseries(
  durationSeconds: number,
  driftRate: number = 0.5 // ms per second
): DriftDetection[] {
  const detections: DriftDetection[] = [];

  for (let t = 0; t < durationSeconds; t++) {
    const drift = driftRate * t + (Math.random() - 0.5) * 5;

    if (drift > 20) {
      detections.push({
        sensorPair: ['lidar', 'camera'],
        driftAmount: drift,
        timestamp: Date.now() - (durationSeconds - t) * 1000,
        severity: drift < 50 ? 'medium' : drift < 100 ? 'high' : 'critical'
      });
    }
  }

  return detections;
}
