import { useRef, useMemo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Grid } from '@react-three/drei';
import * as THREE from 'three';
import { SensorReading, LiDARData } from '../types';

interface SensorVisualizationProps {
  readings: SensorReading[];
  highlightDrift?: boolean;
}

function PointCloud({ reading }: { reading: SensorReading }) {
  const pointsRef = useRef<THREE.Points>(null);

  const { geometry, colors } = useMemo(() => {
    if (reading.sensorType !== 'lidar') return { geometry: null, colors: null };

    const data = reading.data as LiDARData;
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(data.points, 3));

    // Color by intensity
    const colors = new Float32Array(data.points.length);
    for (let i = 0; i < data.intensity.length; i++) {
      const intensity = data.intensity[i];
      colors[i * 3] = intensity;
      colors[i * 3 + 1] = intensity * 0.8;
      colors[i * 3 + 2] = intensity * 0.6;
    }
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    return { geometry, colors };
  }, [reading]);

  useFrame(() => {
    if (pointsRef.current) {
      pointsRef.current.rotation.z += 0.001;
    }
  });

  if (!geometry) return null;

  return (
    <points ref={pointsRef}>
      <bufferGeometry {...geometry} />
      <pointsMaterial size={0.05} vertexColors sizeAttenuation />
    </points>
  );
}

function SensorAxes() {
  return (
    <group>
      {/* X axis - Red */}
      <arrowHelper args={[new THREE.Vector3(1, 0, 0), new THREE.Vector3(0, 0, 0), 2, 0xff0000]} />
      {/* Y axis - Green */}
      <arrowHelper args={[new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, 0, 0), 2, 0x00ff00]} />
      {/* Z axis - Blue */}
      <arrowHelper args={[new THREE.Vector3(0, 0, 1), new THREE.Vector3(0, 0, 0), 2, 0x0000ff]} />
    </group>
  );
}

function VehicleModel() {
  return (
    <group>
      {/* Simple vehicle representation */}
      <mesh position={[0, 0, 0.5]}>
        <boxGeometry args={[2, 1, 0.8]} />
        <meshStandardMaterial color="#2a2a2a" />
      </mesh>
      {/* Camera position */}
      <mesh position={[0.8, 0, 0.9]}>
        <sphereGeometry args={[0.1]} />
        <meshStandardMaterial color="#00ff00" emissive="#00ff00" emissiveIntensity={0.5} />
      </mesh>
      {/* LiDAR position */}
      <mesh position={[0, 0, 1.2]}>
        <cylinderGeometry args={[0.15, 0.15, 0.2]} />
        <meshStandardMaterial color="#0088ff" emissive="#0088ff" emissiveIntensity={0.5} />
      </mesh>
    </group>
  );
}

function Scene({ readings, highlightDrift }: SensorVisualizationProps) {
  const lidarReadings = readings.filter(r => r.sensorType === 'lidar');

  return (
    <>
      <PerspectiveCamera makeDefault position={[10, 10, 10]} />
      <OrbitControls />

      <ambientLight intensity={0.5} />
      <directionalLight position={[10, 10, 5]} intensity={0.5} />

      <Grid args={[50, 50]} cellColor="#444" sectionColor="#666" />

      <VehicleModel />
      <SensorAxes />

      {lidarReadings.slice(0, 1).map((reading, i) => (
        <PointCloud key={i} reading={reading} />
      ))}

      {highlightDrift && (
        <mesh position={[5, 0, 2]}>
          <sphereGeometry args={[0.3]} />
          <meshStandardMaterial color="#ff0000" emissive="#ff0000" emissiveIntensity={1} />
        </mesh>
      )}
    </>
  );
}

export default function SensorVisualization(props: SensorVisualizationProps) {
  return (
    <div style={{ width: '100%', height: '100%', background: '#0a0a0a' }}>
      <Canvas>
        <Scene {...props} />
      </Canvas>
    </div>
  );
}
