import { SensorReading, LiDARData, CameraData, IMUData, CalibrationParams } from '../types';

/**
 * Generate realistic sensor data for demo
 */

export function generateLiDARReading(
  timestamp: number,
  sensorId: string = 'lidar-0',
  withNoise: boolean = true
): SensorReading {
  // Simulate 360-degree LiDAR scan (1024 points)
  const numPoints = 1024;
  const points = new Float32Array(numPoints * 3);
  const intensity = new Float32Array(numPoints);

  for (let i = 0; i < numPoints; i++) {
    const angle = (i / numPoints) * Math.PI * 2;
    const distance = 10 + Math.random() * 20; // 10-30 meters
    const noise = withNoise ? (Math.random() - 0.5) * 0.1 : 0;

    points[i * 3] = Math.cos(angle) * (distance + noise);
    points[i * 3 + 1] = Math.sin(angle) * (distance + noise);
    points[i * 3 + 2] = -1.5 + Math.random() * 3; // Height variation

    intensity[i] = Math.random();
  }

  const data: LiDARData = {
    points,
    intensity,
    scanFrequency: 10 // 10 Hz
  };

  return {
    timestamp,
    sensorId,
    sensorType: 'lidar',
    data
  };
}

export function generateCameraReading(
  timestamp: number,
  sensorId: string = 'camera-0'
): SensorReading {
  const data: CameraData = {
    frame: null, // Simplified for performance
    resolution: [1920, 1080],
    exposureTime: 33, // 33ms @ 30fps
    focalLength: 3.6 // mm
  };

  return {
    timestamp,
    sensorId,
    sensorType: 'camera',
    data
  };
}

export function generateIMUReading(
  timestamp: number,
  sensorId: string = 'imu-0',
  motion: { accel: [number, number, number], gyro: [number, number, number] } | null = null
): SensorReading {
  const baseAccel: [number, number, number] = motion?.accel || [0, 0, 9.81]; // Gravity
  const baseGyro: [number, number, number] = motion?.gyro || [0, 0, 0];

  const data: IMUData = {
    acceleration: [
      baseAccel[0] + (Math.random() - 0.5) * 0.1,
      baseAccel[1] + (Math.random() - 0.5) * 0.1,
      baseAccel[2] + (Math.random() - 0.5) * 0.1
    ],
    gyroscope: [
      baseGyro[0] + (Math.random() - 0.5) * 0.01,
      baseGyro[1] + (Math.random() - 0.5) * 0.01,
      baseGyro[2] + (Math.random() - 0.5) * 0.01
    ],
    magnetometer: [
      20 + (Math.random() - 0.5) * 2,
      -10 + (Math.random() - 0.5) * 2,
      -45 + (Math.random() - 0.5) * 2
    ],
    temperature: 25 + (Math.random() - 0.5) * 2
  };

  return {
    timestamp,
    sensorId,
    sensorType: 'imu',
    data
  };
}

/**
 * Generate a sequence of sensor readings over time
 */
export function generateSensorSequence(
  durationMs: number,
  withDrift: boolean = false,
  driftAmount: number = 0
): SensorReading[] {
  const readings: SensorReading[] = [];
  const startTime = Date.now();

  // LiDAR @ 10Hz
  for (let t = 0; t < durationMs; t += 100) {
    readings.push(generateLiDARReading(startTime + t, 'lidar-0'));
  }

  // Camera @ 30Hz
  for (let t = 0; t < durationMs; t += 33) {
    const drift = withDrift ? t / durationMs * driftAmount : 0;
    readings.push(generateCameraReading(startTime + t + drift, 'camera-0'));
  }

  // IMU @ 100Hz
  for (let t = 0; t < durationMs; t += 10) {
    const drift = withDrift ? t / durationMs * driftAmount * 0.5 : 0;
    readings.push(generateIMUReading(startTime + t + drift, 'imu-0'));
  }

  return readings;
}

/**
 * Default calibration parameters
 */
export function getDefaultCalibration(): CalibrationParams {
  return {
    lidarToCameraTransform: [
      1, 0, 0, 0.1,
      0, 1, 0, 0.0,
      0, 0, 1, 0.2,
      0, 0, 0, 1
    ],
    cameraIntrinsics: [
      1000, 0, 960,
      0, 1000, 540,
      0, 0, 1
    ],
    imuOrientation: [1, 0, 0, 0], // Identity quaternion
    timestampOffsets: {
      lidar: 0,
      camera: 0,
      imu: 0
    }
  };
}

/**
 * Generate calibration with known drift
 */
export function getBadCalibration(): CalibrationParams {
  const cal = getDefaultCalibration();
  return {
    ...cal,
    timestampOffsets: {
      lidar: 0,
      camera: 47, // 47ms drift!
      imu: 12
    }
  };
}

/**
 * Generate point cloud for a specific scenario (e.g., vehicle detection)
 */
export function generateScenarioPointCloud(
  scenario: 'vehicle' | 'pedestrian' | 'clear',
  timestamp: number
): SensorReading {
  const numPoints = 2048;
  const points = new Float32Array(numPoints * 3);
  const intensity = new Float32Array(numPoints);

  let objectCount = 0;

  for (let i = 0; i < numPoints; i++) {
    const angle = (i / numPoints) * Math.PI * 2;
    let distance = 15 + Math.random() * 15;

    // Add objects based on scenario
    if (scenario === 'vehicle' && angle > Math.PI / 3 && angle < Math.PI / 2) {
      // Vehicle at 45 degrees, 10m away
      distance = 10 + (Math.random() - 0.5) * 0.5;
      objectCount++;
    } else if (scenario === 'pedestrian' && angle > Math.PI * 1.5 && angle < Math.PI * 1.6) {
      // Pedestrian at 280 degrees, 5m away
      distance = 5 + (Math.random() - 0.5) * 0.2;
      objectCount++;
    }

    points[i * 3] = Math.cos(angle) * distance;
    points[i * 3 + 1] = Math.sin(angle) * distance;
    points[i * 3 + 2] = -1.5 + Math.random() * 2;

    intensity[i] = objectCount > 0 ? 0.8 : Math.random() * 0.3;
    objectCount = Math.max(0, objectCount - 1);
  }

  const data: LiDARData = {
    points,
    intensity,
    scanFrequency: 10
  };

  return {
    timestamp,
    sensorId: 'lidar-0',
    sensorType: 'lidar',
    data
  };
}
