import { useEffect } from 'react';
import { useStore } from './store';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import CommitHistory from './components/CommitHistory';
import DiffViewer from './components/DiffViewer';
import IncidentReplay from './components/IncidentReplay';
import SensorConfig from './components/SensorConfig';

function App() {
  const { currentView, loadDemoData } = useStore();

  useEffect(() => {
    // Load demo data on mount
    loadDemoData();
  }, [loadDemoData]);

  return (
    <Layout>
      {currentView === 'dashboard' && <Dashboard />}
      {currentView === 'history' && <CommitHistory />}
      {currentView === 'diff' && <DiffViewer />}
      {currentView === 'replay' && <IncidentReplay />}
      {currentView === 'config' && <SensorConfig />}
    </Layout>
  );
}

export default App;
