import { useStore } from '../store';
import { detectDrift } from '../algorithms/driftDetection';
import { computeDelta } from '../algorithms/contentAddressable';

export default function DiffViewer() {
  const { compareCommits } = useStore();
  const [baseCommit, newCommit] = compareCommits;

  if (!baseCommit || !newCommit) {
    return (
      <div style={{ maxWidth: '1200px', margin: '0 auto', textAlign: 'center', padding: '4rem' }}>
        <h2 style={{ fontSize: '1.5rem', marginBottom: '1rem', color: '#888' }}>
          No commits selected for comparison
        </h2>
        <p style={{ color: '#666' }}>
          Select two commits from the history view to compare
        </p>
      </div>
    );
  }

  const delta = computeDelta(baseCommit, newCommit);
  const baseDrifts = detectDrift(baseCommit.sensorReadings);
  const newDrifts = detectDrift(newCommit.sensorReadings);

  return (
    <div style={{ maxWidth: '1400px', margin: '0 auto' }}>
      <div style={{ marginBottom: '2rem' }}>
        <h2 style={{ fontSize: '2rem', marginBottom: '0.5rem' }}>Diff Viewer</h2>
        <p style={{ color: '#888', fontSize: '0.875rem' }}>
          Comparing sensor drift and calibration changes between commits
        </p>
      </div>

      {/* Commit Headers */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: '1fr 1fr',
        gap: '1rem',
        marginBottom: '2rem'
      }}>
        <CommitCard commit={baseCommit} label="Base" color="#ff4444" />
        <CommitCard commit={newCommit} label="Compare" color="#44ff44" />
      </div>

      {/* Drift Comparison */}
      <div style={{
        background: '#1a1a1a',
        border: '1px solid #333',
        borderRadius: '0.5rem',
        padding: '1.5rem',
        marginBottom: '2rem'
      }}>
        <h3 style={{ margin: '0 0 1rem 0', fontSize: '1.25rem' }}>
          Timestamp Drift Analysis
        </h3>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '2rem' }}>
          <div>
            <h4 style={{ fontSize: '0.875rem', color: '#888', marginBottom: '1rem' }}>
              Base Commit ({baseCommit.hash.slice(0, 8)})
            </h4>
            {baseDrifts.length === 0 ? (
              <div style={{ color: '#44ff44', fontSize: '0.875rem' }}>
                ✓ No drift detected
              </div>
            ) : (
              baseDrifts.map((drift, i) => (
                <DriftDisplay key={i} drift={drift} />
              ))
            )}
          </div>

          <div>
            <h4 style={{ fontSize: '0.875rem', color: '#888', marginBottom: '1rem' }}>
              Compare Commit ({newCommit.hash.slice(0, 8)})
            </h4>
            {newDrifts.length === 0 ? (
              <div style={{ color: '#44ff44', fontSize: '0.875rem' }}>
                ✓ No drift detected
              </div>
            ) : (
              newDrifts.map((drift, i) => (
                <DriftDisplay key={i} drift={drift} />
              ))
            )}
          </div>
        </div>

        {/* Drift Improvement/Regression */}
        <div style={{ marginTop: '1.5rem', padding: '1rem', background: '#2a2a2a', borderRadius: '0.5rem' }}>
          {newDrifts.length < baseDrifts.length ? (
            <div style={{ color: '#44ff44' }}>
              ✓ Improvement: {baseDrifts.length - newDrifts.length} drift(s) resolved
            </div>
          ) : newDrifts.length > baseDrifts.length ? (
            <div style={{ color: '#ff4444' }}>
              ⚠ Regression: {newDrifts.length - baseDrifts.length} new drift(s) introduced
            </div>
          ) : (
            <div style={{ color: '#888' }}>
              → No change in drift count
            </div>
          )}
        </div>
      </div>

      {/* Calibration Changes */}
      <div style={{
        background: '#1a1a1a',
        border: '1px solid #333',
        borderRadius: '0.5rem',
        padding: '1.5rem',
        marginBottom: '2rem'
      }}>
        <h3 style={{ margin: '0 0 1rem 0', fontSize: '1.25rem' }}>
          Calibration Parameter Changes
        </h3>

        {Object.keys(delta.calibrationDiff).length === 0 ? (
          <div style={{ color: '#888', fontSize: '0.875rem' }}>
            No calibration changes
          </div>
        ) : (
          <div>
            {delta.calibrationDiff.timestampOffsets && (
              <div style={{ marginBottom: '1rem' }}>
                <div style={{ fontSize: '0.875rem', fontWeight: 600, marginBottom: '0.5rem' }}>
                  Timestamp Offsets
                </div>
                <div style={{
                  display: 'grid',
                  gridTemplateColumns: 'auto 1fr 1fr',
                  gap: '0.5rem',
                  fontSize: '0.875rem',
                  fontFamily: 'monospace'
                }}>
                  <div style={{ fontWeight: 600 }}>Sensor</div>
                  <div style={{ color: '#ff4444' }}>Before</div>
                  <div style={{ color: '#44ff44' }}>After</div>

                  {Object.entries(delta.calibrationDiff.timestampOffsets).map(([sensor, offset]) => (
                    <>
                      <div key={`${sensor}-label`}>{sensor}</div>
                      <div key={`${sensor}-before`}>
                        {baseCommit.calibration.timestampOffsets[sensor as keyof typeof baseCommit.calibration.timestampOffsets]}ms
                      </div>
                      <div key={`${sensor}-after`}>{offset}ms</div>
                    </>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Sensor Reading Changes */}
      <div style={{
        background: '#1a1a1a',
        border: '1px solid #333',
        borderRadius: '0.5rem',
        padding: '1.5rem'
      }}>
        <h3 style={{ margin: '0 0 1rem 0', fontSize: '1.25rem' }}>
          Sensor Data Changes
        </h3>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '2rem' }}>
          <div>
            <div style={{ fontSize: '2rem', fontWeight: 700, color: '#4a9eff' }}>
              {baseCommit.sensorReadings.length}
            </div>
            <div style={{ fontSize: '0.875rem', color: '#888' }}>
              Base readings
            </div>
          </div>

          <div>
            <div style={{ fontSize: '2rem', fontWeight: 700, color: '#44ff44' }}>
              +{delta.addedReadings.length}
            </div>
            <div style={{ fontSize: '0.875rem', color: '#888' }}>
              Added
            </div>
          </div>

          <div>
            <div style={{ fontSize: '2rem', fontWeight: 700, color: '#ff4444' }}>
              -{delta.removedReadings.length}
            </div>
            <div style={{ fontSize: '0.875rem', color: '#888' }}>
              Removed
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function CommitCard({ commit, label, color }: any) {
  return (
    <div style={{
      background: '#1a1a1a',
      border: `2px solid ${color}`,
      borderRadius: '0.5rem',
      padding: '1.5rem'
    }}>
      <div style={{ fontSize: '0.75rem', color: '#888', marginBottom: '0.5rem' }}>
        {label}
      </div>
      <div style={{
        fontFamily: 'monospace',
        color: '#4a9eff',
        fontSize: '1rem',
        marginBottom: '0.5rem'
      }}>
        {commit.hash.slice(0, 8)}
      </div>
      <div style={{ fontSize: '0.875rem', marginBottom: '0.5rem' }}>
        {commit.message}
      </div>
      <div style={{ fontSize: '0.75rem', color: '#888' }}>
        {commit.author}
      </div>
    </div>
  );
}

function DriftDisplay({ drift }: any) {
  const severityColors = {
    low: '#88ff88',
    medium: '#ffaa44',
    high: '#ff8844',
    critical: '#ff4444'
  };

  return (
    <div style={{
      padding: '0.75rem',
      background: '#2a2a2a',
      borderRadius: '0.25rem',
      marginBottom: '0.5rem',
      borderLeft: `3px solid ${severityColors[drift.severity]}`
    }}>
      <div style={{ fontSize: '0.875rem', marginBottom: '0.25rem' }}>
        <strong>{drift.sensorPair[0]}</strong> ↔ <strong>{drift.sensorPair[1]}</strong>
      </div>
      <div style={{ fontSize: '0.75rem', color: '#888' }}>
        Drift: <span style={{ color: severityColors[drift.severity], fontWeight: 600 }}>
          {drift.driftAmount.toFixed(1)}ms
        </span>
        {' • '}
        Severity: {drift.severity}
      </div>
    </div>
  );
}
