import { useStore } from '../store';
import { format } from 'date-fns';

export default function Dashboard() {
  const { commits, incidents, branches, activeDrifts, setSelectedIncident, setCompareCommits } = useStore();

  const recentCommits = commits.slice(-5).reverse();
  const criticalDrifts = activeDrifts.filter(d => d.severity === 'critical');

  return (
    <div style={{ maxWidth: '1400px', margin: '0 auto' }}>
      <h2 style={{ fontSize: '2rem', marginBottom: '2rem' }}>Repository Overview</h2>

      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))',
        gap: '1.5rem',
        marginBottom: '2rem'
      }}>
        {/* Stats Cards */}
        <StatCard
          title="Total Commits"
          value={commits.length.toString()}
          icon="◆"
          color="#4a9eff"
        />
        <StatCard
          title="Active Branches"
          value={branches.length.toString()}
          icon="⎇"
          color="#44ff44"
        />
        <StatCard
          title="Incidents"
          value={incidents.length.toString()}
          icon="⚠"
          color="#ffaa44"
        />
        <StatCard
          title="Critical Drifts"
          value={criticalDrifts.length.toString()}
          icon="●"
          color={criticalDrifts.length > 0 ? '#ff4444' : '#888'}
        />
      </div>

      {/* Critical Alerts */}
      {criticalDrifts.length > 0 && (
        <div style={{
          background: 'rgba(255, 68, 68, 0.12)',
          border: '1px solid rgba(255, 68, 68, 0.3)',
          borderRadius: '0.5rem',
          padding: '1.5rem',
          marginBottom: '2rem'
        }}>
          <h3 style={{ margin: '0 0 1rem 0', color: '#ff4444' }}>
            ⚠ Critical Drift Detected
          </h3>
          {criticalDrifts.map((drift, i) => (
            <div key={i} style={{ marginBottom: '0.5rem', fontSize: '0.875rem' }}>
              <strong>{drift.sensorPair.join(' ↔ ')}</strong>:{' '}
              {drift.driftAmount.toFixed(1)}ms drift
            </div>
          ))}
        </div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '2rem' }}>
        {/* Recent Commits */}
        <div style={{
          background: '#1a1a1a',
          border: '1px solid #333',
          borderRadius: '0.5rem',
          padding: '1.5rem'
        }}>
          <h3 style={{ margin: '0 0 1rem 0' }}>Recent Commits</h3>
          {recentCommits.map(commit => (
            <div
              key={commit.hash}
              style={{
                padding: '1rem',
                background: '#2a2a2a',
                borderRadius: '0.25rem',
                marginBottom: '0.75rem',
                cursor: 'pointer',
                transition: 'background 0.2s'
              }}
              onMouseEnter={e => e.currentTarget.style.background = '#333'}
              onMouseLeave={e => e.currentTarget.style.background = '#2a2a2a'}
            >
              <div style={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                marginBottom: '0.5rem'
              }}>
                <span style={{
                  fontFamily: 'monospace',
                  color: '#4a9eff',
                  fontSize: '0.875rem'
                }}>
                  {commit.hash.slice(0, 8)}
                </span>
                <span style={{ fontSize: '0.75rem', color: '#888' }}>
                  {format(commit.timestamp, 'MMM d, HH:mm')}
                </span>
              </div>
              <div style={{ fontSize: '0.875rem', marginBottom: '0.25rem' }}>
                {commit.message}
              </div>
              <div style={{ fontSize: '0.75rem', color: '#888' }}>
                {commit.author}
              </div>
            </div>
          ))}
        </div>

        {/* Active Incidents */}
        <div style={{
          background: '#1a1a1a',
          border: '1px solid #333',
          borderRadius: '0.5rem',
          padding: '1.5rem'
        }}>
          <h3 style={{ margin: '0 0 1rem 0' }}>Incidents</h3>
          {incidents.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '3rem 1rem', color: '#44ff44' }}>
              <div style={{ fontSize: '2.5rem', marginBottom: '0.75rem' }}>✓</div>
              <div style={{ fontSize: '1rem', fontWeight: 600, marginBottom: '0.5rem' }}>
                All Clear
              </div>
              <div style={{ fontSize: '0.875rem', color: '#888' }}>
                No incidents detected. All sensors are synchronized.
              </div>
            </div>
          ) : (
            incidents.map(incident => (
              <div
                key={incident.id}
                onClick={() => setSelectedIncident(incident)}
                style={{
                  padding: '1rem',
                  background: 'linear-gradient(to right, rgba(255, 68, 68, 0.15) 0%, rgba(255, 68, 68, 0.05) 100%)',
                  borderRadius: '0.25rem',
                  marginBottom: '0.75rem',
                  cursor: 'pointer',
                  transition: 'background 0.2s',
                  border: '1px solid #333'
                }}
                onMouseEnter={e => e.currentTarget.style.background = '#333'}
                onMouseLeave={e => e.currentTarget.style.background = 'linear-gradient(to right, rgba(255, 68, 68, 0.15) 0%, rgba(255, 68, 68, 0.05) 100%)'}
              >
                <div style={{
                  fontSize: '0.875rem',
                  fontWeight: 600,
                  marginBottom: '0.5rem',
                  color: '#ff4444'
                }}>
                  {incident.title}
                </div>
                <div style={{ fontSize: '0.75rem', color: '#ccc', marginBottom: '0.5rem' }}>
                  {incident.description}
                </div>
                <div style={{ fontSize: '0.75rem', color: '#888' }}>
                  {incident.drifts.length} drift(s) detected • {incident.annotations.length} annotation(s)
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Branches */}
      <div style={{
        background: '#1a1a1a',
        border: '1px solid #333',
        borderRadius: '0.5rem',
        padding: '1.5rem',
        marginTop: '2rem'
      }}>
        <h3 style={{ margin: '0 0 1rem 0' }}>Branches</h3>
        <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
          {branches.map(branch => (
            <div
              key={branch.name}
              style={{
                padding: '0.75rem 1rem',
                background: branch.name === 'main' ? 'rgba(74, 158, 255, 0.1)' : '#2a2a2a',
                borderRadius: '0.25rem',
                border: '1px solid #444'
              }}
            >
              <div style={{ fontSize: '0.875rem', fontWeight: 600, marginBottom: '0.25rem' }}>
                {branch.name === 'main' ? '● ' : '⎇ '}
                {branch.name}
              </div>
              <div style={{ fontSize: '0.75rem', color: '#888' }}>
                {branch.description}
              </div>
              <div style={{
                fontSize: '0.75rem',
                color: '#4a9eff',
                fontFamily: 'monospace',
                marginTop: '0.25rem'
              }}>
                {branch.commitHash.slice(0, 8)}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Quick Actions */}
      <div style={{
        marginTop: '2rem',
        display: 'flex',
        gap: '1rem'
      }}>
        <button
          onClick={() => {
            if (commits.length >= 2) {
              setCompareCommits([commits[commits.length - 2], commits[commits.length - 1]]);
            }
          }}
          style={{
            padding: '1rem 2rem',
            background: '#4a9eff',
            color: 'white',
            border: 'none',
            borderRadius: '0.5rem',
            fontSize: '0.875rem',
            fontWeight: 600,
            cursor: 'pointer'
          }}
        >
          Compare Latest Commits
        </button>

        {incidents.length > 0 && (
          <button
            onClick={() => setSelectedIncident(incidents[0])}
            style={{
              padding: '1rem 2rem',
              background: '#ff4444',
              color: 'white',
              border: 'none',
              borderRadius: '0.5rem',
              fontSize: '0.875rem',
              fontWeight: 600,
              cursor: 'pointer'
            }}
          >
            Investigate Incident
          </button>
        )}
      </div>
    </div>
  );
}

function StatCard({ title, value, icon, color }: {
  title: string;
  value: string;
  icon: string;
  color: string;
}) {
  return (
    <div style={{
      background: '#1a1a1a',
      border: '1px solid #333',
      borderRadius: '0.5rem',
      padding: '1.5rem'
    }}>
      <div style={{
        fontSize: '2rem',
        marginBottom: '0.5rem'
      }}>
        {icon}
      </div>
      <div style={{
        fontSize: '2rem',
        fontWeight: 700,
        color,
        marginBottom: '0.25rem'
      }}>
        {value}
      </div>
      <div style={{
        fontSize: '0.875rem',
        color: '#888'
      }}>
        {title}
      </div>
    </div>
  );
}
