import { ReactNode } from 'react';
import { useStore } from '../store';

interface LayoutProps {
  children: ReactNode;
}

export default function Layout({ children }: LayoutProps) {
  const { currentView, setCurrentView, currentCommit, activeDrifts } = useStore();

  const views = [
    { id: 'dashboard', label: 'Dashboard', icon: '⌗' },
    { id: 'history', label: 'History', icon: '⎇' },
    { id: 'diff', label: 'Diff', icon: '±' },
    { id: 'replay', label: 'Replay', icon: '▸' },
    { id: 'config', label: 'Config', icon: '⚙' }
  ] as const;

  const hasCriticalDrift = activeDrifts.some(d => d.severity === 'critical');

  return (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      height: '100vh',
      background: 'var(--color-bg-base)',
      color: 'var(--color-text-primary)',
      fontFamily: 'var(--font-sans)'
    }}>
      {/* Header */}
      <header style={{
        background: 'var(--color-bg-elevated)',
        borderBottom: '1px solid var(--color-border-default)',
        padding: 'var(--space-4) var(--space-8)',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center'
      }}>
        <div>
          <h1 style={{ margin: 0, fontSize: 'var(--text-xl)', fontWeight: 'var(--font-semibold)' }}>
            Delby Lineage
          </h1>
          <p style={{ margin: 'var(--space-1) 0 0 0', fontSize: 'var(--text-sm)', color: 'var(--color-text-tertiary)' }}>
            Sensor Data Platform for Autonomous Vehicles
          </p>
        </div>

        {currentCommit && (
          <div style={{
            background: 'var(--color-bg-interactive)',
            padding: 'var(--space-2) var(--space-4)',
            borderRadius: 'var(--radius-md)',
            fontSize: 'var(--text-sm)'
          }}>
            <span style={{ color: 'var(--color-text-tertiary)' }}>Current: </span>
            <span style={{ color: 'var(--color-primary)', fontFamily: 'var(--font-mono)' }}>
              {currentCommit.hash.slice(0, 8)}
            </span>
            <span style={{ color: 'var(--color-text-tertiary)', marginLeft: 'var(--space-4)' }}>
              {currentCommit.message}
            </span>
          </div>
        )}

        {hasCriticalDrift && (
          <div style={{
            background: 'var(--color-error)',
            color: 'white',
            padding: 'var(--space-2) var(--space-4)',
            borderRadius: 'var(--radius-md)',
            fontSize: 'var(--text-sm)',
            fontWeight: 'var(--font-semibold)',
            animation: 'pulse 2s infinite'
          }}>
            ⚠ Critical Drift Detected
          </div>
        )}
      </header>

      {/* Navigation */}
      <nav style={{
        background: 'var(--color-bg-nav)',
        borderBottom: '1px solid var(--color-border-default)',
        display: 'flex',
        gap: 'var(--space-2)',
        padding: '0 var(--space-8)'
      }}>
        {views.map(view => (
          <button
            key={view.id}
            onClick={() => setCurrentView(view.id as any)}
            style={{
              background: currentView === view.id ? 'var(--color-bg-interactive)' : 'transparent',
              border: 'none',
              color: currentView === view.id ? 'var(--color-primary)' : 'var(--color-text-tertiary)',
              padding: 'var(--space-4) var(--space-6)',
              cursor: 'pointer',
              fontSize: 'var(--text-sm)',
              fontWeight: 'var(--font-medium)',
              borderBottom: currentView === view.id ? '2px solid var(--color-primary)' : '2px solid transparent',
              transition: 'all var(--transition-base)'
            }}
          >
            <span style={{ marginRight: 'var(--space-2)' }}>{view.icon}</span>
            {view.label}
          </button>
        ))}
      </nav>

      {/* Main Content */}
      <main style={{
        flex: 1,
        overflow: 'auto',
        padding: 'var(--space-8)'
      }}>
        {children}
      </main>

      {/* Status Bar */}
      <footer style={{
        background: 'var(--color-bg-elevated)',
        borderTop: '1px solid var(--color-border-default)',
        padding: 'var(--space-3) var(--space-8)',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        fontSize: 'var(--text-sm)',
        color: 'var(--color-text-tertiary)'
      }}>
        <div>
          <span style={{ marginRight: 'var(--space-8)' }}>
            <span style={{ color: 'var(--color-success)', marginRight: 'var(--space-1)' }}>●</span>
            LiDAR: Online
          </span>
          <span style={{ marginRight: 'var(--space-8)' }}>
            <span style={{ color: 'var(--color-success)', marginRight: 'var(--space-1)' }}>●</span>
            Camera: Online
          </span>
          <span>
            <span style={{ color: 'var(--color-success)', marginRight: 'var(--space-1)' }}>●</span>
            IMU: Online
          </span>
        </div>

        <div>
          Sync Status:{' '}
          <span style={{ color: hasCriticalDrift ? 'var(--color-error)' : 'var(--color-success)' }}>
            {hasCriticalDrift ? 'DESYNC' : 'SYNCHRONIZED'}
          </span>
          {activeDrifts.length > 0 && (
            <span style={{ marginLeft: 'var(--space-4)' }}>
              Max Drift: {Math.max(...activeDrifts.map(d => d.driftAmount)).toFixed(1)}ms
            </span>
          )}
        </div>
      </footer>

      <style>{`
        @keyframes pulse {
          0%, 100% { opacity: 1; }
          50% { opacity: 0.7; }
        }

        button:hover {
          opacity: 0.8;
        }

        * {
          box-sizing: border-box;
        }

        body {
          margin: 0;
          overflow: hidden;
        }

        ::-webkit-scrollbar {
          width: 10px;
        }

        ::-webkit-scrollbar-track {
          background: #1a1a1a;
        }

        ::-webkit-scrollbar-thumb {
          background: #444;
          border-radius: 5px;
        }

        ::-webkit-scrollbar-thumb:hover {
          background: #555;
        }
      `}</style>
    </div>
  );
}
