import { useStore } from '../store';
import { format } from 'date-fns';
import { SensorCommit } from '../types';

export default function CommitHistory() {
  const { commits, setCurrentCommit, setCompareCommits, currentCommit } = useStore();

  const sortedCommits = [...commits].sort((a, b) =>
    b.timestamp.getTime() - a.timestamp.getTime()
  );

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
      <div style={{ marginBottom: '2rem' }}>
        <h2 style={{ fontSize: '2rem', marginBottom: '0.5rem' }}>Commit History</h2>
        <p style={{ color: '#888', fontSize: '0.875rem' }}>
          Git-like version control for sensor data and calibration parameters
        </p>
      </div>

      <div style={{
        background: '#1a1a1a',
        border: '1px solid #333',
        borderRadius: '0.5rem',
        overflow: 'hidden'
      }}>
        {/* Header */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: '80px 1fr 200px 150px 100px',
          padding: '1rem',
          background: '#151515',
          borderBottom: '1px solid #333',
          fontSize: '0.875rem',
          fontWeight: 600,
          color: '#888'
        }}>
          <div>Hash</div>
          <div>Message</div>
          <div>Author</div>
          <div>Date</div>
          <div>Actions</div>
        </div>

        {/* Commit List */}
        <div>
          {sortedCommits.map((commit, index) => (
            <CommitRow
              key={commit.hash}
              commit={commit}
              isSelected={currentCommit?.hash === commit.hash}
              onSelect={() => setCurrentCommit(commit)}
              onCompare={() => {
                if (index < sortedCommits.length - 1) {
                  setCompareCommits([sortedCommits[index + 1], commit]);
                }
              }}
            />
          ))}
        </div>
      </div>

      {/* Commit Graph Visualization */}
      <div style={{
        marginTop: '2rem',
        background: '#1a1a1a',
        border: '1px solid #333',
        borderRadius: '0.5rem',
        padding: '1.5rem'
      }}>
        <h3 style={{ margin: '0 0 1rem 0' }}>Commit Graph</h3>
        <CommitGraph commits={sortedCommits} />
      </div>
    </div>
  );
}

function CommitRow({
  commit,
  isSelected,
  onSelect,
  onCompare
}: {
  commit: SensorCommit;
  isSelected: boolean;
  onSelect: () => void;
  onCompare: () => void;
}) {
  const hasDrift = commit.sensorReadings.length > 0;
  const hasTag = commit.tags.length > 0;

  return (
    <div
      onClick={onSelect}
      style={{
        display: 'grid',
        gridTemplateColumns: '80px 1fr 200px 150px 100px',
        padding: '1rem',
        borderBottom: '1px solid #333',
        background: isSelected ? '#2a3a4a' : 'transparent',
        cursor: 'pointer',
        transition: 'background 0.2s'
      }}
      onMouseEnter={e => {
        if (!isSelected) e.currentTarget.style.background = '#252525';
      }}
      onMouseLeave={e => {
        if (!isSelected) e.currentTarget.style.background = 'transparent';
      }}
    >
      <div style={{
        fontFamily: 'monospace',
        color: '#4a9eff',
        fontSize: '0.875rem'
      }}>
        {commit.hash.slice(0, 8)}
      </div>

      <div style={{ fontSize: '0.875rem' }}>
        {commit.message}
        {hasTag && (
          <span style={{
            marginLeft: '0.5rem',
            padding: '0.125rem 0.5rem',
            background: '#44aa44',
            color: 'white',
            borderRadius: '0.25rem',
            fontSize: '0.75rem',
            fontWeight: 600
          }}>
            {commit.tags[0]}
          </span>
        )}
      </div>

      <div style={{ fontSize: '0.875rem', color: '#888' }}>
        {commit.author}
      </div>

      <div style={{ fontSize: '0.875rem', color: '#888' }}>
        {format(commit.timestamp, 'MMM d, HH:mm')}
      </div>

      <div style={{ display: 'flex', gap: '0.5rem' }}>
        <button
          onClick={(e) => {
            e.stopPropagation();
            onCompare();
          }}
          style={{
            padding: '0.25rem 0.5rem',
            background: '#333',
            color: '#ccc',
            border: 'none',
            borderRadius: '0.25rem',
            fontSize: '0.75rem',
            cursor: 'pointer'
          }}
        >
          Diff
        </button>
      </div>
    </div>
  );
}

function CommitGraph({ commits }: { commits: SensorCommit[] }) {
  const maxCommits = 15;
  const displayCommits = commits.slice(0, maxCommits);

  return (
    <svg width="100%" height={displayCommits.length * 60 + 40} style={{ overflow: 'visible' }}>
      {/* Draw connections */}
      {displayCommits.map((commit, i) => {
        if (commit.parentHash) {
          const parentIndex = displayCommits.findIndex(c => c.hash === commit.parentHash);
          if (parentIndex !== -1) {
            return (
              <line
                key={`line-${i}`}
                x1={30}
                y1={i * 60 + 30}
                x2={30}
                y2={parentIndex * 60 + 30}
                stroke="#4a9eff"
                strokeWidth={2}
              />
            );
          }
        }
        return null;
      })}

      {/* Draw commits */}
      {displayCommits.map((commit, i) => (
        <g key={commit.hash} transform={`translate(0, ${i * 60})`}>
          <circle
            cx={30}
            cy={30}
            r={8}
            fill={commit.tags.length > 0 ? '#44aa44' : '#4a9eff'}
            stroke="#1a1a1a"
            strokeWidth={3}
          />
          <text
            x={50}
            y={35}
            fill="#e0e0e0"
            fontSize="14"
            fontFamily="monospace"
          >
            {commit.hash.slice(0, 8)} - {commit.message}
          </text>
          {commit.tags.length > 0 && (
            <rect
              x={250}
              y={23}
              width={60}
              height={18}
              rx={4}
              fill="#44aa44"
            />
          )}
          {commit.tags.length > 0 && (
            <text
              x={280}
              y={35}
              fill="white"
              fontSize="12"
              fontWeight="600"
              textAnchor="middle"
            >
              {commit.tags[0]}
            </text>
          )}
        </g>
      ))}
    </svg>
  );
}
