import { create } from 'zustand';
import { SensorCommit, IncidentReport, Branch, DriftDetection } from './types';
import { createFullHistory, createIncidentScenario, createBranchScenario } from './data/incidents';

interface AppState {
  // Commits and version history
  commits: SensorCommit[];
  currentCommit: SensorCommit | null;
  branches: Branch[];

  // Incident tracking
  incidents: IncidentReport[];
  selectedIncident: IncidentReport | null;

  // Playback state
  isPlaying: boolean;
  playbackTime: number; // ms from start
  playbackSpeed: number; // 1.0 = realtime

  // Drift monitoring
  activeDrifts: DriftDetection[];

  // UI state
  currentView: 'dashboard' | 'history' | 'diff' | 'replay' | 'config';
  compareCommits: [SensorCommit | null, SensorCommit | null];

  // Actions
  loadDemoData: () => void;
  setCurrentCommit: (commit: SensorCommit) => void;
  setSelectedIncident: (incident: IncidentReport | null) => void;
  setPlaybackTime: (time: number) => void;
  togglePlayback: () => void;
  setPlaybackSpeed: (speed: number) => void;
  setCurrentView: (view: AppState['currentView']) => void;
  setCompareCommits: (commits: [SensorCommit | null, SensorCommit | null]) => void;
  createNewBranch: (name: string, fromCommit: SensorCommit) => void;
}

export const useStore = create<AppState>((set, get) => ({
  commits: [],
  currentCommit: null,
  branches: [
    { name: 'main', commitHash: '', description: 'Production calibration' }
  ],
  incidents: [],
  selectedIncident: null,
  isPlaying: false,
  playbackTime: 0,
  playbackSpeed: 1.0,
  activeDrifts: [],
  currentView: 'dashboard',
  compareCommits: [null, null],

  loadDemoData: () => {
    const commits = createFullHistory();
    const { incident } = createIncidentScenario();
    const { mainCommits, branchCommits } = createBranchScenario();

    // Combine all commits
    const allCommits = [...commits, ...mainCommits, ...branchCommits];

    // Update branches
    const branches: Branch[] = [
      {
        name: 'main',
        commitHash: commits[commits.length - 1]?.hash || '',
        description: 'Production calibration'
      },
      {
        name: 'experimental-sync',
        commitHash: branchCommits[branchCommits.length - 1]?.hash || '',
        description: 'Testing optimized timestamp synchronization'
      }
    ];

    set({
      commits: allCommits,
      currentCommit: commits[commits.length - 1] || null,
      incidents: [incident],
      branches,
      activeDrifts: incident.drifts
    });
  },

  setCurrentCommit: (commit) => {
    set({ currentCommit: commit });
  },

  setSelectedIncident: (incident) => {
    set({
      selectedIncident: incident,
      currentView: incident ? 'replay' : get().currentView
    });
  },

  setPlaybackTime: (time) => {
    set({ playbackTime: time });
  },

  togglePlayback: () => {
    set({ isPlaying: !get().isPlaying });
  },

  setPlaybackSpeed: (speed) => {
    set({ playbackSpeed: speed });
  },

  setCurrentView: (view) => {
    set({ currentView: view });
  },

  setCompareCommits: (commits) => {
    set({ compareCommits: commits, currentView: 'diff' });
  },

  createNewBranch: (name, fromCommit) => {
    const newBranch: Branch = {
      name,
      commitHash: fromCommit.hash,
      description: `Branch from ${fromCommit.hash.slice(0, 8)}`
    };

    set({
      branches: [...get().branches, newBranch]
    });
  }
}));

// Auto-play simulation
if (typeof window !== 'undefined') {
  setInterval(() => {
    const state = useStore.getState();
    if (state.isPlaying && state.selectedIncident) {
      const maxTime = 30000; // 30 seconds
      const newTime = (state.playbackTime + 100 * state.playbackSpeed) % maxTime;
      state.setPlaybackTime(newTime);
    }
  }, 100);
}
