import { SensorCommit, CalibrationParams, SensorReading } from '../types';

/**
 * Content-addressable storage using SHA-256-like hashing
 * Simplified implementation for demo purposes
 */
export function computeCommitHash(
  parentHash: string | null,
  timestamp: Date,
  author: string,
  message: string,
  calibration: CalibrationParams,
  readings: SensorReading[]
): string {
  // Serialize commit data
  const data = {
    parent: parentHash,
    timestamp: timestamp.toISOString(),
    author,
    message,
    calibration: JSON.stringify(calibration),
    readingsHash: computeReadingsHash(readings)
  };

  return simpleHash(JSON.stringify(data));
}

function computeReadingsHash(readings: SensorReading[]): string {
  // Hash sensor readings efficiently
  const summary = readings.map(r => ({
    ts: r.timestamp,
    type: r.sensorType,
    id: r.sensorId
  }));

  return simpleHash(JSON.stringify(summary));
}

/**
 * Simple hash function (mimics SHA-256 for demo)
 */
function simpleHash(input: string): string {
  let hash = 0;
  for (let i = 0; i < input.length; i++) {
    const char = input.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32bit integer
  }

  // Convert to hex-like string
  const hex = Math.abs(hash).toString(16).padStart(8, '0');
  return `${hex}${Date.now().toString(16).slice(-8)}`;
}

/**
 * Create a new commit in the version control system
 */
export function createCommit(
  parentCommit: SensorCommit | null,
  author: string,
  message: string,
  calibration: CalibrationParams,
  readings: SensorReading[]
): SensorCommit {
  const timestamp = new Date();
  const parentHash = parentCommit ? parentCommit.hash : null;

  const hash = computeCommitHash(
    parentHash,
    timestamp,
    author,
    message,
    calibration,
    readings
  );

  return {
    hash,
    parentHash,
    timestamp,
    author,
    message,
    calibration,
    sensorReadings: readings,
    branches: parentCommit?.branches || ['main'],
    tags: []
  };
}

/**
 * Compute delta between two commits for efficient storage
 */
export function computeDelta(
  baseCommit: SensorCommit,
  newCommit: SensorCommit
): {
  calibrationDiff: Partial<CalibrationParams>;
  addedReadings: SensorReading[];
  removedReadings: string[];
} {
  // Calibration differences
  const calibrationDiff: Partial<CalibrationParams> = {};

  if (JSON.stringify(baseCommit.calibration.timestampOffsets) !==
      JSON.stringify(newCommit.calibration.timestampOffsets)) {
    calibrationDiff.timestampOffsets = newCommit.calibration.timestampOffsets;
  }

  if (JSON.stringify(baseCommit.calibration.lidarToCameraTransform) !==
      JSON.stringify(newCommit.calibration.lidarToCameraTransform)) {
    calibrationDiff.lidarToCameraTransform = newCommit.calibration.lidarToCameraTransform;
  }

  // Reading differences
  const baseIds = new Set(baseCommit.sensorReadings.map(r => r.sensorId));
  const newIds = new Set(newCommit.sensorReadings.map(r => r.sensorId));

  const addedReadings = newCommit.sensorReadings.filter(r => !baseIds.has(r.sensorId));
  const removedReadings = Array.from(baseIds).filter(id => !newIds.has(id));

  return {
    calibrationDiff,
    addedReadings,
    removedReadings
  };
}

/**
 * Merge two branches (simplified three-way merge)
 */
export function mergeBranches(
  baseCommit: SensorCommit,
  branchA: SensorCommit,
  branchB: SensorCommit,
  author: string
): SensorCommit {
  // Merge calibration (prefer branchB if conflict)
  const mergedCalibration: CalibrationParams = {
    ...baseCommit.calibration,
    ...branchA.calibration,
    ...branchB.calibration
  };

  // Merge readings (union of both branches)
  const readingsMap = new Map<string, SensorReading>();

  [...branchA.sensorReadings, ...branchB.sensorReadings].forEach(reading => {
    readingsMap.set(reading.sensorId, reading);
  });

  const mergedReadings = Array.from(readingsMap.values());

  return createCommit(
    branchB,
    author,
    `Merge branch '${branchA.branches[0]}' into '${branchB.branches[0]}'`,
    mergedCalibration,
    mergedReadings
  );
}

/**
 * Find common ancestor for merge operations
 */
export function findCommonAncestor(
  commitA: SensorCommit,
  commitB: SensorCommit,
  allCommits: Map<string, SensorCommit>
): SensorCommit | null {
  const ancestorsA = new Set<string>();

  let current: SensorCommit | null = commitA;
  while (current) {
    ancestorsA.add(current.hash);
    current = current.parentHash ? allCommits.get(current.parentHash) || null : null;
  }

  current = commitB;
  while (current) {
    if (ancestorsA.has(current.hash)) {
      return current;
    }
    current = current.parentHash ? allCommits.get(current.parentHash) || null : null;
  }

  return null;
}
