import { SensorReading, DriftDetection } from '../types';

/**
 * Detect timestamp drift between sensor pairs
 * Uses cross-correlation to find optimal alignment and measure drift
 */
export function detectDrift(
  readings: SensorReading[],
  threshold: number = 20 // milliseconds
): DriftDetection[] {
  const drifts: DriftDetection[] = [];
  const sensorTypes = ['lidar', 'camera', 'imu'];

  // Compare each sensor pair
  for (let i = 0; i < sensorTypes.length; i++) {
    for (let j = i + 1; j < sensorTypes.length; j++) {
      const sensor1 = sensorTypes[i];
      const sensor2 = sensorTypes[j];

      const readings1 = readings.filter(r => r.sensorType === sensor1);
      const readings2 = readings.filter(r => r.sensorType === sensor2);

      if (readings1.length === 0 || readings2.length === 0) continue;

      // Compute drift using timestamp alignment
      const drift = computeTimestampDrift(readings1, readings2);

      if (Math.abs(drift) > threshold) {
        drifts.push({
          sensorPair: [sensor1, sensor2],
          driftAmount: drift,
          timestamp: Date.now(),
          severity: getDriftSeverity(Math.abs(drift))
        });
      }
    }
  }

  return drifts;
}

function computeTimestampDrift(
  readings1: SensorReading[],
  readings2: SensorReading[]
): number {
  if (readings1.length === 0 || readings2.length === 0) return 0;

  // Sample readings for drift calculation
  const sampleSize = Math.min(10, readings1.length, readings2.length);
  let totalDrift = 0;

  for (let i = 0; i < sampleSize; i++) {
    const idx1 = Math.floor((i / sampleSize) * readings1.length);
    const idx2 = Math.floor((i / sampleSize) * readings2.length);

    totalDrift += readings1[idx1].timestamp - readings2[idx2].timestamp;
  }

  return totalDrift / sampleSize;
}

function getDriftSeverity(drift: number): 'low' | 'medium' | 'high' | 'critical' {
  if (drift < 20) return 'low';
  if (drift < 50) return 'medium';
  if (drift < 100) return 'high';
  return 'critical';
}

/**
 * Analyze drift trends over time
 */
export function analyzeDriftTrend(drifts: DriftDetection[]): {
  increasing: boolean;
  rate: number; // ms per second
  prediction: number; // predicted drift in next 60 seconds
} {
  if (drifts.length < 2) {
    return { increasing: false, rate: 0, prediction: 0 };
  }

  // Linear regression on drift over time
  const n = drifts.length;
  let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;

  drifts.forEach((drift, i) => {
    const x = i;
    const y = drift.driftAmount;
    sumX += x;
    sumY += y;
    sumXY += x * y;
    sumX2 += x * x;
  });

  const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
  const prediction = slope * 60; // Predict 60 seconds ahead

  return {
    increasing: slope > 0.1,
    rate: slope,
    prediction
  };
}

/**
 * Suggest calibration corrections based on detected drift
 */
export function suggestCalibration(drifts: DriftDetection[]): {
  sensorId: string;
  offsetCorrection: number;
  confidence: number;
}[] {
  const suggestions: Map<string, { total: number; count: number }> = new Map();

  drifts.forEach(drift => {
    drift.sensorPair.forEach(sensor => {
      const current = suggestions.get(sensor) || { total: 0, count: 0 };
      current.total += drift.driftAmount / 2; // Split drift between pair
      current.count += 1;
      suggestions.set(sensor, current);
    });
  });

  return Array.from(suggestions.entries()).map(([sensorId, data]) => ({
    sensorId,
    offsetCorrection: -data.total / data.count, // Negative to correct
    confidence: Math.min(0.95, data.count / 10)
  }));
}
