import { useEffect } from 'react';
import { useStore } from '../store';
import SensorVisualization from './SensorVisualization';
import { format } from 'date-fns';

export default function IncidentReplay() {
  const {
    selectedIncident,
    playbackTime,
    isPlaying,
    playbackSpeed,
    setPlaybackTime,
    togglePlayback,
    setPlaybackSpeed,
    commits
  } = useStore();

  useEffect(() => {
    // Auto-play simulation
    if (isPlaying && selectedIncident) {
      const interval = setInterval(() => {
        setPlaybackTime((playbackTime + 100 * playbackSpeed) % 30000);
      }, 100);
      return () => clearInterval(interval);
    }
  }, [isPlaying, playbackTime, playbackSpeed, selectedIncident, setPlaybackTime]);

  if (!selectedIncident) {
    return (
      <div style={{ maxWidth: '600px', margin: '0 auto', textAlign: 'center', padding: '6rem 2rem' }}>
        <div style={{ fontSize: '3rem', marginBottom: '1.5rem', opacity: 0.3 }}>▸</div>
        <h2 style={{ fontSize: '1.5rem', marginBottom: '0.75rem', color: '#e0e0e0' }}>
          Select an Incident to Replay
        </h2>
        <p style={{ color: '#888', marginBottom: '2rem', lineHeight: 1.6 }}>
          Go to the Dashboard and click on an incident to reproduce and analyze sensor data with frame-accurate timeline playback.
        </p>
        <button
          onClick={() => window.location.hash = '#dashboard'}
          style={{
            padding: '0.75rem 1.5rem',
            background: '#4a9eff',
            color: 'white',
            border: 'none',
            borderRadius: '0.5rem',
            fontSize: '0.875rem',
            fontWeight: 600,
            cursor: 'pointer'
          }}
        >
          Go to Dashboard
        </button>
      </div>
    );
  }

  const commit = commits.find(c => c.hash === selectedIncident.commitHash);
  if (!commit) return null;

  const maxTime = 30000; // 30 seconds
  const progress = (playbackTime / maxTime) * 100;

  // Filter readings for current playback time
  const currentReadings = commit.sensorReadings.filter(r => {
    const relativeTime = r.timestamp - commit.sensorReadings[0].timestamp;
    return relativeTime <= playbackTime;
  });

  return (
    <div style={{ maxWidth: '1600px', margin: '0 auto' }}>
      <div style={{ marginBottom: '2rem' }}>
        <h2 style={{ fontSize: '2rem', marginBottom: '0.5rem' }}>
          Incident Replay
        </h2>
        <p style={{ color: '#888', fontSize: '0.875rem' }}>
          Reproduce and analyze sensor data incidents with exact state reconstruction
        </p>
      </div>

      {/* Incident Info */}
      <div style={{
        background: 'linear-gradient(135deg, rgba(255, 68, 68, 0.08) 0%, rgba(255, 68, 68, 0.03) 100%)',
        border: '1px solid rgba(255, 68, 68, 0.3)',
        borderRadius: '0.5rem',
        padding: '1.5rem',
        marginBottom: '2rem'
      }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start' }}>
          <div>
            <h3 style={{ margin: '0 0 0.5rem 0', fontSize: '1.25rem', color: '#ff4444' }}>
              {selectedIncident.title}
            </h3>
            <p style={{ margin: '0 0 1rem 0', color: '#ccc', fontSize: '0.875rem' }}>
              {selectedIncident.description}
            </p>
            <div style={{ fontSize: '0.875rem', color: '#888' }}>
              Commit:{' '}
              <span style={{ fontFamily: 'monospace', color: '#4a9eff' }}>
                {selectedIncident.commitHash.slice(0, 8)}
              </span>
              {' • '}
              {format(selectedIncident.timestamp, 'MMM d, yyyy HH:mm:ss')}
            </div>
          </div>

          <div style={{
            background: '#2a2a2a',
            padding: '1rem',
            borderRadius: '0.5rem',
            minWidth: '200px'
          }}>
            <div style={{ fontSize: '0.75rem', color: '#888', marginBottom: '0.5rem' }}>
              Detected Drifts
            </div>
            {selectedIncident.drifts.map((drift, i) => (
              <div key={i} style={{ fontSize: '0.875rem', marginBottom: '0.25rem' }}>
                <strong>{drift.sensorPair.join(' ↔ ')}</strong>:{' '}
                <span style={{
                  color: drift.severity === 'critical' ? '#ff4444' : '#ffaa44',
                  fontWeight: 600
                }}>
                  {drift.driftAmount.toFixed(1)}ms
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Main Content: 3D Visualization + Timeline */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: '2fr 1fr',
        gap: '2rem',
        marginBottom: '2rem'
      }}>
        {/* 3D Visualization */}
        <div style={{
          background: '#1a1a1a',
          border: '1px solid #333',
          borderRadius: '0.5rem',
          overflow: 'hidden',
          height: '500px'
        }}>
          <SensorVisualization
            readings={currentReadings}
            highlightDrift={playbackTime > 15000}
          />
        </div>

        {/* Sensor Status */}
        <div style={{
          background: '#1a1a1a',
          border: '1px solid #333',
          borderRadius: '0.5rem',
          padding: '1.5rem'
        }}>
          <h3 style={{ margin: '0 0 1rem 0', fontSize: '1.25rem' }}>
            Sensor Status
          </h3>

          <SensorStatus
            name="LiDAR"
            icon="●"
            healthy={true}
            readings={currentReadings.filter(r => r.sensorType === 'lidar').length}
            drift={0}
          />
          <SensorStatus
            name="Camera"
            icon="●"
            healthy={playbackTime < 15000}
            readings={currentReadings.filter(r => r.sensorType === 'camera').length}
            drift={playbackTime > 15000 ? 47 : 0}
          />
          <SensorStatus
            name="IMU"
            icon="●"
            healthy={true}
            readings={currentReadings.filter(r => r.sensorType === 'imu').length}
            drift={12}
          />

          <div style={{
            marginTop: '2rem',
            padding: '1rem',
            background: playbackTime > 15000 ? 'rgba(255, 68, 68, 0.15)' : 'rgba(68, 255, 68, 0.15)',
            borderRadius: '0.5rem',
            border: '1px solid rgba(255, 255, 255, 0.1)'
          }}>
            <div style={{
              fontSize: '0.875rem',
              fontWeight: 600,
              color: playbackTime > 15000 ? '#ff4444' : '#44ff44',
              marginBottom: '0.5rem'
            }}>
              {playbackTime > 15000 ? '⚠ DESYNC DETECTED' : '✓ SYNCHRONIZED'}
            </div>
            <div style={{ fontSize: '0.75rem', color: '#888' }}>
              Max drift: {playbackTime > 15000 ? '47.3' : '12.1'}ms
            </div>
          </div>
        </div>
      </div>

      {/* Playback Controls */}
      <div style={{
        background: '#1a1a1a',
        border: '1px solid #333',
        borderRadius: '0.5rem',
        padding: '1.5rem'
      }}>
        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: '1rem',
          marginBottom: '1rem'
        }}>
          <button
            onClick={togglePlayback}
            style={{
              padding: '0.75rem 1.5rem',
              background: '#4a9eff',
              color: 'white',
              border: 'none',
              borderRadius: '0.5rem',
              fontSize: '1rem',
              cursor: 'pointer',
              fontWeight: 600
            }}
          >
            {isPlaying ? '‖' : '▸'}
          </button>

          <div style={{ flex: 1 }}>
            <input
              type="range"
              min={0}
              max={maxTime}
              value={playbackTime}
              onChange={(e) => setPlaybackTime(Number(e.target.value))}
              style={{
                width: '100%',
                height: '8px',
                background: `linear-gradient(to right, #4a9eff ${progress}%, #333 ${progress}%)`,
                borderRadius: '4px',
                outline: 'none',
                cursor: 'pointer'
              }}
            />
            <div style={{
              display: 'flex',
              justifyContent: 'space-between',
              marginTop: '0.5rem',
              fontSize: '0.75rem',
              color: '#888'
            }}>
              <span>{(playbackTime / 1000).toFixed(1)}s</span>
              <span>{(maxTime / 1000).toFixed(1)}s</span>
            </div>
          </div>

          <select
            value={playbackSpeed}
            onChange={(e) => setPlaybackSpeed(Number(e.target.value))}
            style={{
              padding: '0.75rem',
              background: '#2a2a2a',
              color: 'white',
              border: '1px solid #444',
              borderRadius: '0.5rem',
              cursor: 'pointer'
            }}
          >
            <option value={0.25}>0.25x</option>
            <option value={0.5}>0.5x</option>
            <option value={1}>1x</option>
            <option value={2}>2x</option>
            <option value={4}>4x</option>
          </select>
        </div>

        {/* Timeline markers */}
        <div style={{ position: 'relative', height: '20px', marginTop: '1rem' }}>
          {selectedIncident.drifts.map((drift, i) => (
            <div
              key={i}
              style={{
                position: 'absolute',
                left: '50%',
                width: '2px',
                height: '20px',
                background: '#ff4444',
                transform: 'translateX(-50%)'
              }}
              title={`${drift.sensorPair.join(' ↔ ')}: ${drift.driftAmount.toFixed(1)}ms`}
            />
          ))}
        </div>
      </div>

      {/* Annotations */}
      <div style={{
        background: '#1a1a1a',
        border: '1px solid #333',
        borderRadius: '0.5rem',
        padding: '1.5rem',
        marginTop: '2rem'
      }}>
        <h3 style={{ margin: '0 0 1rem 0', fontSize: '1.25rem' }}>
          Annotations
        </h3>
        {selectedIncident.annotations.map(annotation => (
          <div
            key={annotation.id}
            style={{
              padding: '1rem',
              background: '#2a2a2a',
              borderRadius: '0.5rem',
              marginBottom: '0.75rem',
              borderLeft: '3px solid #4a9eff'
            }}
          >
            <div style={{
              display: 'flex',
              justifyContent: 'space-between',
              marginBottom: '0.5rem'
            }}>
              <span style={{ fontSize: '0.875rem', fontWeight: 600 }}>
                {annotation.author}
              </span>
              <span style={{ fontSize: '0.75rem', color: '#888' }}>
                {format(annotation.timestamp, 'MMM d, HH:mm')}
              </span>
            </div>
            <div style={{ fontSize: '0.875rem', color: '#ccc' }}>
              {annotation.text}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function SensorStatus({
  name,
  icon,
  healthy,
  readings,
  drift
}: {
  name: string;
  icon: string;
  healthy: boolean;
  readings: number;
  drift: number;
}) {
  return (
    <div style={{
      padding: '1rem',
      background: '#2a2a2a',
      borderRadius: '0.5rem',
      marginBottom: '0.75rem',
      borderLeft: `3px solid ${healthy ? '#44ff44' : '#ff4444'}`
    }}>
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center'
      }}>
        <div>
          <div style={{ fontSize: '0.875rem', fontWeight: 600, marginBottom: '0.25rem' }}>
            {icon} {name}
          </div>
          <div style={{ fontSize: '0.75rem', color: '#888' }}>
            {readings} readings
          </div>
        </div>
        <div style={{ textAlign: 'right' }}>
          <div style={{
            fontSize: '0.75rem',
            color: healthy ? '#44ff44' : '#ff4444',
            fontWeight: 600
          }}>
            {healthy ? 'HEALTHY' : 'DRIFT'}
          </div>
          {drift > 0 && (
            <div style={{ fontSize: '0.75rem', color: '#888' }}>
              {drift}ms
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
